async function runTool(db, act, ctx) {
  const tool = String(act?.tool || 'direct_answer');
  const args = act?.args || {};
  const { BRAND, BRIDGE_SECRET, N8N_INTERNAL, TG_TRADER_TOK, TG_CEO_TOK, DISCORD_TOK } = cfg();
  const rctx = _RCTX || {};

  if (tool === 'get_market_prices') {
    return { tool, ok: true, livePrices: ctx.livePrices };
  }

  if (tool === 'get_system_kpis') {
    return { tool, ok: true, ...(ctx.stats || {}), livePrices: ctx.livePrices };
  }

  if (tool === 'trigger_workflow') {
    const wfPath = String(args.workflow_path || '').replace(/^\/+/, '');
    if (!wfPath) return { tool, ok: false, error: 'Missing workflow_path' };
    try {
      const hdrs = { 'Content-Type': 'application/json' };
      if (BRIDGE_SECRET) hdrs['x-tradesejon-secret'] = BRIDGE_SECRET;
      const r = await safeFetch(`${N8N_INTERNAL}/webhook/${wfPath}`, {
        method: 'POST',
        headers: hdrs,
        body: JSON.stringify(args.payload || {})
      });
      return { tool, ok: r.ok, workflow: wfPath, status: r.status };
    } catch (e) {
      return { tool, ok: false, workflow: wfPath, error: e.message };
    }
  }

  if (tool === 'search_system') {
    const q = String(args.query || ctx.prompt || '').trim();
    const scope = String(args.scope || 'all').toLowerCase();
    const out = { tool, ok: true, crm: [], tickets: [], knowledge: [] };
    const rx = new RegExp(q.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'i');
    if (db) {
      if (scope === 'all' || scope === 'crm') {
        const leads = await db.collection('trading_leads').find({ $or: [{ full_name: rx }, { email: rx }, { phone: rx }] }).limit(5).toArray().catch(() => []);
        const contacts = await db.collection('contacts').find({ $or: [{ full_name: rx }, { name: rx }, { email: rx }, { phone: rx }] }).limit(5).toArray().catch(() => []);
        out.crm = [...leads, ...contacts].map(d => ({ name: d.full_name || d.name || 'Lead', email: d.email || '', phone: d.phone || '', status: d.status || '' }));
      }
      if (scope === 'all' || scope === 'knowledge') {
        const kb = await db.collection('kb_articles').find({ $or: [{ title: rx }, { content: rx }] }).limit(5).toArray().catch(() => []);
        out.knowledge = kb.map(k => ({ title: k.title, snippet: String(k.content || '').slice(0, 180) }));
      }
    }
    if (out.knowledge.length === 0 && (scope === 'all' || scope === 'knowledge') && Array.isArray(rctx.kbItems)) {
      out.knowledge = rctx.kbItems.filter(k => rx.test(`${k.title || ''} ${k.content || ''}`)).slice(0, 5)
        .map(k => ({ title: k.title, snippet: String(k.content || '').slice(0, 180) }));
    }
    return out;
  }

  if (tool === 'list_knowledge') {
    let items = db ? await db.collection('kb_articles').find({}).sort({ updated_at: -1 }).limit(20).toArray().catch(() => []) : [];
    if ((!items || items.length === 0) && Array.isArray(rctx.kbItems)) {
      items = rctx.kbItems;
    }
    return { tool, ok: true, count: items.length, items: items.map(i => ({ title: i.title, slug: i.slug })) };
  }

  if (tool === 'add_knowledge') {
    const title = String(args.title || 'Synced Rule').trim();
    const content = String(args.content || '').trim();
    const category = String(args.category || 'general');
    if (!content) return { tool, ok: false, error: 'Missing knowledge content' };
    const slug = (title.toLowerCase().replace(/[^a-z0-9\u0600-\u06FF]+/g, '_').replace(/^_+|_+$/g, '').slice(0, 48) || 'rule') + '_' + Date.now().toString(36).slice(-4);
    if (db) {
      await db.collection('kb_articles').updateOne({ slug }, { $set: { slug, title, category, content, updated_at: new Date() } }, { upsert: true }).catch(() => {});
      await db.collection('knowledge_chunks').insertOne({ slug, title, chunk_index: 0, text: content.slice(0, 2000), updated_at: new Date() }).catch(() => {});
      await db.collection('aios_super_memory').insertOne({ type: 'n8n_knowledge_ingest', slug, title, rule: content, updated_at: new Date() }).catch(() => {});
    }
    return { tool, ok: true, title, slug, content, category, chunks: 1 };
  }

  if (tool === 'delete_knowledge') {
    const q = String(args.slug_or_query || '').trim();
    if (!q || q === '*' || q.toLowerCase() === 'all') return { tool, ok: false, error: 'Wildcard deletion blocked by safety guard.' };
    const rx = new RegExp(q.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'i');
    let doc = db ? await db.collection('kb_articles').findOne({ $or: [{ slug: q }, { title: rx }] }).catch(() => null) : null;
    if (!doc && Array.isArray(rctx.kbItems)) {
      doc = rctx.kbItems.find(i => i.slug === q || rx.test(i.title || '')) || null;
    }
    if (!doc) return { tool, ok: false, error: `No knowledge entry matched "${q}".` };
    if (db) {
      await db.collection('kb_articles').deleteOne({ slug: doc.slug }).catch(() => {});
      await db.collection('knowledge_chunks').deleteMany({ slug: doc.slug }).catch(() => {});
    }
    return { tool, ok: true, deleted_title: doc.title, deleted_slug: doc.slug };
  }

  if (tool === 'add_crm_lead') {
    const name = String(args.name || 'New Lead').trim();
    const email = String(args.email || '').trim().toLowerCase();
    const phone = String(args.phone || '').trim();
    const status = String(args.status || 'prospect');
    if (!email && !phone) return { tool, ok: false, error: 'Provide an email or phone number to save lead.' };
    if (db) {
      const f = email ? { email } : { phone };
